const SB_URL="https://puxzsxhrlghbzatzsiyg.supabase.co";
const SB_KEY="sb_publishable_u0gjKD7XY4z5v5B1-vKFww_0EYGuX22";
const supa=window.supabase.createClient(SB_URL,SB_KEY,{auth:{storageKey:"taller-admin-auth",persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});
const S={brand:localStorage.brand||"#f47a1f",shop:localStorage.shop||"Mi Taller",logoPath:null,logoUrl:null,businessPhone:"",businessEmail:"",businessAddress:"",businessWebsite:"",user:null,profile:null,current:"Dashboard"};
document.documentElement.style.setProperty("--brand",S.brand);
const modules=["Dashboard","Órdenes","Clientes","Empleados","Cotizaciones","Facturas","Recibos","PDF","Inventario","Reportes","Ajustes"];
const esc=v=>String(v??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#039;"}[m]));
const statusLabel=s=>({pending:"Pendiente",assigned:"Asignada",en_route:"En camino",diagnosis:"Diagnóstico",waiting_parts:"Esperando piezas",repair:"En reparación",quality_check:"Control de calidad",work_finished:"Trabajo terminado",closed:"Cerrada",cancelled:"Cancelada"}[s]||s||"");
async function loadBranding(){const {data}=await supa.from("app_settings").select("shop_name,brand_color,logo_path,business_phone,business_email,business_address,business_website").eq("id",1).maybeSingle();if(data){S.shop=data.shop_name||S.shop;S.brand=data.brand_color||S.brand;S.logoPath=data.logo_path||null;S.businessPhone=data.business_phone||"";S.businessEmail=data.business_email||"";S.businessAddress=data.business_address||"";S.businessWebsite=data.business_website||"";if(S.logoPath){const {data:pub}=supa.storage.from("branding").getPublicUrl(S.logoPath);S.logoUrl=pub?.publicUrl||null}localStorage.shop=S.shop;localStorage.brand=S.brand;document.documentElement.style.setProperty("--brand",S.brand)}}
function brandMark(label="TA"){return S.logoUrl?'<div class="logoMark"><img src="'+esc(S.logoUrl)+'" alt="Logo"></div>':'<div class="mark">'+label+'</div>'}
let adminChannel=null;function subscribeAdminRealtime(){if(adminChannel)return;adminChannel=supa.channel("admin-operations").on("postgres_changes",{event:"*",schema:"public",table:"work_orders"},()=>content(S.current)).on("postgres_changes",{event:"*",schema:"public",table:"diagnostics"},()=>{if(S.current==="Órdenes")content("Órdenes")}).on("postgres_changes",{event:"*",schema:"public",table:"work_order_parts"},()=>{if(["Órdenes","Inventario","Dashboard"].includes(S.current))content(S.current)}).on("postgres_changes",{event:"*",schema:"public",table:"inventory_items"},()=>{if(["Inventario","Dashboard"].includes(S.current))content(S.current)}).subscribe()}
async function init(){await loadBranding();const {data:{session}}=await supa.auth.getSession();if(session){S.user=session.user;await loadProfile();subscribeAdminRealtime()}render();supa.auth.onAuthStateChange(async(_,session)=>{S.user=session?.user||null;if(S.user){await loadProfile();subscribeAdminRealtime()}else S.profile=null;render()})}
async function loadProfile(){await supa.rpc("claim_initial_admin");const {data}=await supa.from("profiles").select("*").eq("id",S.user.id).single();S.profile=data}
async function login(){const email=document.querySelector("#email").value.trim();const password=document.querySelector("#pass").value;const btn=document.querySelector("#loginBtn");if(!email||!password)return alert("Escribe email y contraseña.");if(btn){btn.disabled=true;btn.textContent="Entrando..."}try{const {data,error}=await supa.auth.signInWithPassword({email,password});if(error)throw error;if(!data?.session)throw new Error("No se pudo iniciar la sesión.");S.user=data.user;await loadProfile();if(!S.profile||!["admin","manager"].includes(S.profile.role))return render();subscribeAdminRealtime();render()}catch(e){alert("No se pudo iniciar sesión: "+(e.message||"Error desconocido"))}finally{if(btn){btn.disabled=false;btn.textContent="Entrar"}}}
const ADMIN_REDIRECT="https://eliezelapolinaris2017-lab.github.io/-taller-admin/";
async function signup(){const email=document.querySelector("#email").value.trim();const password=document.querySelector("#pass").value;if(password.length<8)return alert("La contraseña debe tener al menos 8 caracteres.");const {data,error}=await supa.auth.signUp({email,password,options:{data:{full_name:"Administrador"},emailRedirectTo:ADMIN_REDIRECT}});if(error)return alert(error.message);localStorage.pendingAdminEmail=email;alert(data.session?"Cuenta creada. Entrando...":"Cuenta creada. Revisa el email de confirmación. El enlace regresará al panel administrativo.")}
async function resendConfirmation(){const email=(document.querySelector("#email")?.value||localStorage.pendingAdminEmail||"").trim();if(!email)return alert("Escribe el email de administrador.");const {error}=await supa.auth.resend({type:"signup",email,options:{emailRedirectTo:ADMIN_REDIRECT}});if(error)return alert(error.message);alert("Te envié un enlace nuevo de confirmación. Usa solamente el más reciente.")}
async function logout(){await supa.auth.signOut()}
function authView(){return '<div class="login"><div class="card"><div class="brand">'+brandMark("TA")+'<span>'+esc(S.shop||"Taller Admin")+'</span></div><p class="muted">Acceso administrativo seguro</p><label>Email</label><input id="email" type="email" placeholder="admin@taller.com"><label>Contraseña</label><input id="pass" type="password" placeholder="8+ caracteres"><button id="loginBtn" class="btn" onclick="login()">Entrar</button> <button class="btn secondary" onclick="signup()">Crear primer administrador</button><button class="btn secondary" style="margin-top:10px;width:100%" onclick="resendConfirmation()">Reenviar confirmación</button><p class="muted small">La primera cuenta creada puede reclamar el rol de administrador. Si un enlace expiró, usa Reenviar confirmación y abre solamente el email más reciente.</p></div></div>'}
function render(){const a=document.querySelector("#app");if(!S.user){a.innerHTML=authView();return}if(!S.profile||!["admin","manager"].includes(S.profile.role)){a.innerHTML='<div class="login"><div class="card"><h2>Acceso restringido</h2><p>Esta cuenta no tiene permisos administrativos.</p><button class="btn" onclick="logout()">Salir</button></div></div>';return}a.innerHTML='<div class="shell"><aside class="side"><div class="brand">'+brandMark("TA")+'<span>'+esc(S.shop)+'</span></div><div class="nav">'+modules.map(m=>'<button data-n="'+m+'" class="'+(m===S.current?"active":"")+'" onclick="nav(\''+m+'\')">'+m+'</button>').join("")+'</div></aside><main class="main"><div class="top"><div><b>Panel administrativo</b><div class="muted">'+esc(S.profile.full_name||S.user.email)+' · '+esc(S.profile.role)+'</div></div><button class="btn" onclick="logout()">Salir</button></div><section id="content"><div class="card">Cargando...</div></section></main></div>';content(S.current)}
function nav(name){S.current=name;render()}
async function content(name){const c=document.querySelector("#content");if(!c)return;if(name==="Dashboard")return dashboard(c);if(name==="Órdenes")return orders(c);if(name==="Clientes")return customers(c);if(name==="Empleados")return employees(c);if(name==="Inventario")return inventory(c);if(name==="Cotizaciones")return quotes(c);if(name==="Facturas")return invoices(c);if(name==="Recibos")return receipts(c);if(name==="PDF")return pdfCenter(c);if(name==="Reportes")return reports(c);if(name==="Ajustes")return settings(c)}
async function dashboard(c){const [{count:orders},{count:pending},{count:customers},{count:low}]=await Promise.all([supa.from("work_orders").select("*",{count:"exact",head:true}),supa.from("work_orders").select("*",{count:"exact",head:true}).neq("status","closed").neq("status","cancelled"),supa.from("customers").select("*",{count:"exact",head:true}),supa.from("inventory_items").select("*",{count:"exact",head:true}).lte("quantity",0)]);const {data:recent}=await supa.from("work_orders").select("id,order_number,title,status,created_at,vehicles(make,model,year)").order("created_at",{ascending:false}).limit(6);c.innerHTML='<div class="heroBanner"><div class="heroCopy"><div class="eyebrow">SISTEMA DE ADMINISTRACIÓN PARA TALLERES</div><h2>Gestiona tu taller con mayor control, organización y rapidez.</h2><p>Controla órdenes de trabajo, clientes, empleados, inventario, cotizaciones, facturación y cobros desde un solo lugar.</p><span class="heroTag">OPERACIÓN CENTRALIZADA EN TIEMPO REAL</span></div></div><h1>Dashboard</h1><p class="muted">Resumen ejecutivo del taller.</p><div class="grid"><div class="metric">Órdenes activas<strong>'+(orders||0)+'</strong><small>Operación total</small></div><div class="metric">En proceso<strong>'+(pending||0)+'</strong><small>Seguimiento activo</small></div><div class="metric">Clientes<strong>'+(customers||0)+'</strong><small>Base registrada</small></div><div class="metric">Inventario crítico<strong>'+(low||0)+'</strong><small>Requiere atención</small></div></div><div class="dashboardActivity"><div class="card sectionCard"><div class="sectionTitle"><h3>Actividad reciente</h3><span class="pill">En vivo</span></div><div class="list">'+((recent||[]).slice(0,4).map(o=>'<div class="row"><span><b>OT-'+o.order_number+'</b><br><span class="muted">'+esc(o.title)+'</span></span><span class="pill">'+esc(statusLabel(o.status))+'</span></div>').join("")||'<p class="muted">Aún no hay órdenes.</p>')+'</div></div><div class="card sectionCard"><div class="sectionTitle"><h3>Órdenes de trabajo recientes</h3><span class="muted">Últimos movimientos</span></div><div class="list">'+((recent||[]).map(o=>'<div class="row"><span><b>OT-'+o.order_number+'</b> · '+esc(o.vehicles?.year||"")+' '+esc(o.vehicles?.make||"")+' '+esc(o.vehicles?.model||"")+'<br><span class="muted">'+esc(o.title)+'</span></span><span class="pill">'+esc(statusLabel(o.status))+'</span></div>').join("")||'<p class="muted">Aún no hay órdenes.</p>')+'</div></div></div>'}
async function customers(c){const {data:list}=await supa.from("customers").select("*,vehicles(*)").order("created_at",{ascending:false});c.innerHTML='<div class="sectionHead"><div><h1>Clientes y vehículos</h1><p class="muted">Base maestra del taller.</p></div><button class="btn" onclick="showCustomerForm()">+ Cliente</button></div><div id="customerForm"></div><div class="list">'+((list||[]).map(x=>'<div class="card"><div class="row"><b>'+esc(x.name)+'</b><span class="muted">'+esc(x.phone||"")+'</span></div><div class="muted">'+esc(x.email||"")+'</div><div class="chips">'+(x.vehicles||[]).map(v=>'<span class="pill">'+esc(v.year||"")+' '+esc(v.make||"")+' '+esc(v.model||"")+' '+esc(v.plate||"")+'</span>').join(" ")+'</div><button class="btn smallbtn" onclick="showVehicleForm(\''+x.id+'\',\''+esc(x.name).replace(/'/g,"&#39;")+'\')">+ Vehículo</button></div>').join("")||'<div class="card muted">No hay clientes.</div>')+'</div>'}
function showCustomerForm(){document.querySelector("#customerForm").innerHTML='<div class="card formcard"><h3>Nuevo cliente</h3><div class="formgrid"><input id="cn" placeholder="Nombre"><input id="cp" placeholder="Teléfono"><input id="ce" type="email" placeholder="Email"><input id="ca" placeholder="Dirección"></div><button class="btn" onclick="saveCustomer()">Guardar cliente</button></div>'}
async function saveCustomer(){const payload={name:document.querySelector("#cn").value.trim(),phone:document.querySelector("#cp").value.trim(),email:document.querySelector("#ce").value.trim(),address:document.querySelector("#ca").value.trim(),created_by:S.user.id};if(!payload.name)return alert("Nombre requerido");const {error}=await supa.from("customers").insert(payload);if(error)return alert(error.message);customers(document.querySelector("#content"))}
function showVehicleForm(cid,name){document.querySelector("#customerForm").innerHTML='<div class="card formcard"><h3>Nuevo vehículo · '+name+'</h3><div class="formgrid"><input id="vy" type="number" placeholder="Año"><input id="vmk" placeholder="Marca"><input id="vmd" placeholder="Modelo"><input id="vpl" placeholder="Tablilla"><input id="vvin" placeholder="VIN"><input id="vmi" type="number" placeholder="Millaje"></div><button class="btn" onclick="saveVehicle(\''+cid+'\')">Guardar vehículo</button></div>'}
async function saveVehicle(cid){const p={customer_id:cid,year:+document.querySelector("#vy").value||null,make:document.querySelector("#vmk").value.trim(),model:document.querySelector("#vmd").value.trim(),plate:document.querySelector("#vpl").value.trim(),vin:document.querySelector("#vvin").value.trim(),mileage:+document.querySelector("#vmi").value||null};const {error}=await supa.from("vehicles").insert(p);if(error)return alert(error.message);customers(document.querySelector("#content"))}
async function orders(c){const [{data:list},{data:customers},{data:profiles}]=await Promise.all([supa.from("work_orders").select("*,customers(name),vehicles(year,make,model,plate),work_order_assignments(user_id,profiles(full_name))").order("created_at",{ascending:false}),supa.from("customers").select("id,name,vehicles(id,year,make,model,plate)").order("name"),supa.from("profiles").select("id,full_name,role").eq("active",true).order("full_name")]);window._orderCustomers=customers||[];window._profiles=profiles||[];c.innerHTML='<div class="sectionHead"><div><h1>Órdenes de trabajo</h1><p class="muted">Todo lo que actualice el mecánico aparece aquí.</p></div><button class="btn" onclick="showOrderForm()">+ Orden</button></div><div id="orderForm"></div><div class="list">'+((list||[]).map(o=>'<div class="card"><div class="row"><div><b>OT-'+o.order_number+' · '+esc(o.title)+'</b><div class="muted">'+esc(o.customers?.name||"")+' · '+esc(o.vehicles?.year||"")+' '+esc(o.vehicles?.make||"")+' '+esc(o.vehicles?.model||"")+'</div></div><span class="pill">'+esc(statusLabel(o.status))+'</span></div><div class="muted">Mecánico asignado: '+esc((o.work_order_assignments||[]).map(a=>a.profiles?.full_name).filter(Boolean).join(", ")||"Sin asignar")+'</div><div class="actions"><select id="st-'+o.id+'"><option value="'+o.status+'">'+statusLabel(o.status)+'</option>'+["pending","assigned","en_route","diagnosis","waiting_parts","repair","quality_check","work_finished","closed","cancelled"].filter(s=>s!==o.status).map(s=>'<option value="'+s+'">'+statusLabel(s)+'</option>').join("")+'</select><button class="btn smallbtn" onclick="updateOrderStatus(\''+o.id+'\')">Actualizar</button><button class="btn secondary smallbtn" onclick="openAdminOrder(\''+o.id+'\')">Ver detalle</button></div></div>').join("")||'<div class="card muted">No hay órdenes.</div>')+'</div>'}

async function openAdminOrder(id){const [{data:o},{data:diags},{data:parts},{data:evidence},{data:activity},{data:staff}]=await Promise.all([supa.from("work_orders").select("*,customers(name,phone,email),vehicles(year,make,model,plate,mileage),work_order_assignments(user_id,profiles(full_name,role))").eq("id",id).single(),supa.from("diagnostics").select("*,profiles:author_id(full_name)").eq("work_order_id",id).order("created_at",{ascending:false}),supa.from("work_order_parts").select("*,inventory_items(name,sku)").eq("work_order_id",id).order("created_at",{ascending:false}),supa.from("evidence").select("*,profiles:uploaded_by(full_name)").eq("work_order_id",id).order("created_at",{ascending:false}),supa.from("activity_log").select("*,profiles:actor_id(full_name)").eq("entity_type","work_order").eq("entity_id",id).order("created_at",{ascending:false}),supa.from("profiles").select("id,full_name,role").eq("active",true).in("role",["manager","mechanic","helper"]).order("full_name")]);if(!o)return alert("No se pudo abrir la orden.");window._detailStaff=staff||[];const assignedIds=new Set((o.work_order_assignments||[]).map(a=>a.user_id));document.querySelector("#content").innerHTML='<button class="btn" onclick="orders(document.querySelector(\'#content\'))">← Volver a órdenes</button><div class="card" style="margin-top:14px"><div class="sectionHead"><div><h2>OT-'+o.order_number+' · '+esc(o.title)+'</h2><div class="muted">'+esc(o.customers?.name||"")+' · '+esc(o.customers?.phone||"")+' · '+esc(o.vehicles?.year||"")+' '+esc(o.vehicles?.make||"")+' '+esc(o.vehicles?.model||"")+' · '+esc(o.vehicles?.plate||"")+'</div></div><span class="pill">'+esc(statusLabel(o.status))+'</span></div><div class="actions" style="margin-top:14px"><button class="btn" onclick="showQuickCharge(\''+id+'\')">Cobrar / Facturar</button>'+(o.status!=="closed"?'<button class="btn secondary" onclick="closeAdminOrder(\''+id+'\')">Cerrar orden</button>':'<span class="pill">Orden cerrada</span>')+'</div><div id="quickChargeBox"></div><hr><h3>Mecánicos asignados</h3><div class="list">'+((o.work_order_assignments||[]).map(a=>'<div class="row"><span><b>'+esc(a.profiles?.full_name||"Empleado")+'</b></span><span class="pill">'+esc(a.profiles?.role||"")+'</span></div>').join("")||'<div class="muted">Sin mecánico asignado.</div>')+'</div><div class="formgrid" style="margin-top:12px"><select id="extraTech"><option value="">Añadir otro empleado...</option>'+(staff||[]).filter(p=>!assignedIds.has(p.id)).map(p=>'<option value="'+p.id+'">'+esc(p.full_name||p.role)+' · '+esc(p.role)+'</option>').join("")+'</select><button class="btn" onclick="assignTechnician(\''+id+'\')">Asignar al equipo</button></div><hr><h3>Diagnóstico / actualizaciones</h3><div class="list">'+((diags||[]).map(d=>'<div class="job"><b>'+esc(d.profiles?.full_name||"Técnico")+'</b><div class="muted">'+new Date(d.created_at).toLocaleString()+'</div><p>'+esc(d.findings||"")+'</p><div class="muted">Pruebas: '+esc(d.tests_performed||"—")+'</div><div class="muted">Códigos: '+esc(d.trouble_codes||"—")+'</div><div>Recomendación: '+esc(d.recommendation||"—")+'</div></div>').join("")||'<div class="muted">Sin diagnóstico todavía.</div>')+'</div><hr><h3>Piezas utilizadas</h3><div class="list">'+((parts||[]).map(p=>'<div class="row"><span><b>'+esc(p.description)+'</b><br><span class="muted">'+esc(p.inventory_items?.sku||"")+' · Descontada de inventario</span></span><span>'+esc(p.quantity)+' × $'+Number(p.unit_price||0).toFixed(2)+'</span></div>').join("")||'<div class="muted">Sin piezas registradas.</div>')+'</div><hr><h3>Evidencias</h3><div class="list">'+((evidence||[]).map(ev=>'<div class="row"><span><b>'+esc(ev.file_name||"Archivo")+'</b><br><span class="muted">'+esc(ev.profiles?.full_name||"Empleado")+' · '+esc(ev.note||"")+'</span></span><span>'+new Date(ev.created_at).toLocaleString()+'</span></div>').join("")||'<div class="muted">Sin evidencias.</div>')+'</div><hr><h3>Historial de la orden</h3><div class="list">'+((activity||[]).map(a=>'<div class="row"><span><b>'+esc(a.profiles?.full_name||"Sistema")+'</b><br><span class="muted">'+esc(a.action.replaceAll("_"," "))+'</span></span><span>'+new Date(a.created_at).toLocaleString()+'</span></div>').join("")||'<div class="muted">Sin movimientos registrados todavía.</div>')+'</div></div>'}
function showQuickCharge(orderId){document.querySelector("#quickChargeBox").innerHTML='<div class="card formcard" style="margin-top:14px"><h3>Cobro rápido</h3><input id="chargeDesc" placeholder="Descripción del trabajo / servicio"><input id="chargeAmount" type="number" step="0.01" placeholder="Importe antes de IVU"><input id="chargeTax" type="number" step="0.01" placeholder="IVU / impuesto"><input id="chargePaid" type="number" step="0.01" placeholder="Pago recibido ahora (opcional)"><select id="chargeMethod"><option value="">Método de pago</option><option>Efectivo</option><option>ATH Móvil</option><option>Tarjeta</option><option>Cheque</option><option>Transferencia</option></select><input id="chargeRef" placeholder="Referencia (opcional)"><button class="btn" onclick="quickCharge(\''+orderId+'\')">Crear factura y registrar pago</button></div>'}
async function quickCharge(orderId){const amount=+document.querySelector("#chargeAmount").value||0,tax=+document.querySelector("#chargeTax").value||0,paid=+document.querySelector("#chargePaid").value||0,desc=document.querySelector("#chargeDesc").value.trim(),method=document.querySelector("#chargeMethod").value||null,reference=document.querySelector("#chargeRef").value.trim()||null;if(amount<0||tax<0||paid<0)return alert("Revisa las cantidades.");if(paid>0&&!method)return alert("Selecciona método de pago.");const {data,error}=await supa.rpc("quick_charge_work_order",{p_order:orderId,p_description:desc,p_amount:amount,p_tax:tax,p_payment_amount:paid,p_payment_method:method,p_reference:reference});if(error)return alert(error.message);alert("Factura creada"+(paid>0?" y pago registrado.":"."));S.current="Facturas";render()}
async function closeAdminOrder(orderId){if(!confirm("¿Cerrar esta orden de trabajo como completada?"))return;const {error}=await supa.rpc("close_work_order",{p_order:orderId});if(error)return alert(error.message);alert("Orden cerrada.");openAdminOrder(orderId)}
async function assignTechnician(orderId){const user_id=document.querySelector("#extraTech").value;if(!user_id)return alert("Selecciona un empleado.");const {error}=await supa.from("work_order_assignments").insert({work_order_id:orderId,user_id,assigned_by:S.user.id});if(error)return alert(error.message);await supa.from("work_orders").update({status:"assigned",updated_at:new Date().toISOString()}).eq("id",orderId);openAdminOrder(orderId)}
function showOrderForm(){const cs=window._orderCustomers||[],ps=window._profiles||[];document.querySelector("#orderForm").innerHTML='<div class="card formcard"><h3>Nueva orden</h3><label>Cliente / vehículo</label><select id="ov"><option value="">Seleccione...</option>'+cs.flatMap(c=>(c.vehicles||[]).map(v=>'<option value="'+v.id+'" data-c="'+c.id+'">'+esc(c.name)+' · '+esc(v.year||"")+' '+esc(v.make||"")+' '+esc(v.model||"")+' '+esc(v.plate||"")+'</option>')).join("")+'</select><input id="ot" placeholder="Trabajo / título"><textarea id="oc" rows="3" placeholder="Queja o solicitud del cliente"></textarea><label>Asignar empleado</label><select id="oa"><option value="">Sin asignar</option>'+ps.filter(p=>["mechanic","helper","manager"].includes(p.role)).map(p=>'<option value="'+p.id+'">'+esc(p.full_name||p.role)+'</option>').join("")+'</select><button class="btn" onclick="saveOrder()">Crear orden</button></div>'}
async function saveOrder(){const sel=document.querySelector("#ov"),vehicle_id=sel.value,customer_id=sel.selectedOptions[0]?.dataset.c,title=document.querySelector("#ot").value.trim(),assignee=document.querySelector("#oa").value;if(!vehicle_id||!title)return alert("Selecciona vehículo y escribe el trabajo.");const {data,error}=await supa.from("work_orders").insert({customer_id,vehicle_id,title,complaint:document.querySelector("#oc").value.trim(),status:assignee?"assigned":"pending",created_by:S.user.id}).select().single();if(error)return alert(error.message);if(assignee)await supa.from("work_order_assignments").insert({work_order_id:data.id,user_id:assignee,assigned_by:S.user.id});orders(document.querySelector("#content"))}
async function updateOrderStatus(id){const status=document.querySelector("#st-"+id).value;const patch={status,updated_at:new Date().toISOString()};if(status==="completed")patch.completed_at=new Date().toISOString();const {error}=await supa.from("work_orders").update(patch).eq("id",id);if(error)return alert(error.message);orders(document.querySelector("#content"))}
async function employees(c){const {data:list}=await supa.from("profiles").select("*").order("created_at");window._employees=list||[];c.innerHTML='<div class="sectionHead"><div><h1>Empleados</h1><p class="muted">Usuarios, permisos y foto de perfil.</p></div><button class="btn" onclick="showEmployeeForm()">+ Empleado</button></div><div id="employeeForm"></div><div class="list">'+((list||[]).map(p=>'<div class="row"><span class="employeeIdentity">'+(p.avatar_url?'<img class="avatar sm" src="'+esc(p.avatar_url)+'" alt="Foto">':'<div class="avatar fallback sm">'+esc(((p.full_name||p.email||"E").split(" ").map(x=>x[0]).join("").slice(0,2).toUpperCase()))+'</div>')+'<span><b>'+esc(p.full_name||p.email)+'</b><br><span class="muted">'+esc(p.email||"")+'</span></span></span><span><span class="pill">'+esc(p.role)+'</span> <button class="btn secondary smallbtn" onclick="openEmployeeProfile(\''+p.id+'\')">Perfil</button></span></div>').join(""))+'</div>'}
function openEmployeeProfile(id){const p=(window._employees||[]).find(x=>x.id===id);if(!p)return;document.querySelector("#content").innerHTML='<button class="btn" onclick="employees(document.querySelector(\'#content\'))">← Volver</button><div class="card" style="margin-top:14px"><div class="profileHero">'+(p.avatar_url?'<img class="avatar lg" src="'+esc(p.avatar_url)+'" alt="Foto">':'<div class="avatar fallback lg">'+esc(((p.full_name||p.email||"E").split(" ").map(x=>x[0]).join("").slice(0,2).toUpperCase()))+'</div>')+'<div><h2>'+esc(p.full_name||p.email)+'</h2><div class="muted">'+esc(p.role)+' · '+esc(p.email||"")+'</div></div></div><hr><label>Actualizar foto del empleado</label><input id="adminAvatarFile" type="file" accept="image/png,image/jpeg,image/webp"><button class="btn" onclick="adminUpdateAvatar(\''+p.id+'\')">Guardar foto</button></div>'}
async function adminUpdateAvatar(id){const file=document.querySelector("#adminAvatarFile")?.files?.[0];if(!file)return alert("Selecciona una foto.");if(file.size>5*1024*1024)return alert("La foto excede 5 MB.");const safe=file.name.replace(/[^a-zA-Z0-9._-]/g,"_"),path=id+"/"+Date.now()+"-"+safe;const {error:upErr}=await supa.storage.from("avatars").upload(path,file,{cacheControl:"3600"});if(upErr)return alert(upErr.message);const {data:pub}=supa.storage.from("avatars").getPublicUrl(path);const {error}=await supa.from("profiles").update({avatar_url:pub?.publicUrl||null,updated_at:new Date().toISOString()}).eq("id",id);if(error)return alert(error.message);alert("Foto actualizada.");employees(document.querySelector("#content"))}
function showEmployeeForm(){document.querySelector("#employeeForm").innerHTML='<div class="card formcard"><h3>Crear acceso de empleado</h3><div class="formgrid"><input id="en" placeholder="Nombre completo"><input id="ee" type="email" placeholder="Email"><input id="ep" type="password" placeholder="Contraseña temporal (8+)"><select id="er"><option value="mechanic">Mecánico</option><option value="helper">Ayudante</option><option value="manager">Gerente</option></select></div><button class="btn" onclick="createEmployee()">Crear usuario</button></div>'}
async function createEmployee(){const body={full_name:document.querySelector("#en").value.trim(),email:document.querySelector("#ee").value.trim(),password:document.querySelector("#ep").value,role:document.querySelector("#er").value};const {data,error}=await supa.functions.invoke("create-employee",{body});if(error)return alert(error.message);if(data?.error)return alert(data.error);alert("Empleado creado.");employees(document.querySelector("#content"))}
async function inventory(c){const {data:list}=await supa.from("inventory_items").select("*").order("name");c.innerHTML='<div class="sectionHead"><div><h1>Inventario</h1><p class="muted">Piezas, consumibles y existencias.</p></div><button class="btn" onclick="showInventoryForm()">+ Artículo</button></div><div id="inventoryForm"></div><div class="list">'+((list||[]).map(i=>'<div class="row"><span><b>'+esc(i.name)+'</b><br><span class="muted">'+esc(i.sku||"")+' · '+esc(i.location||"")+'</span></span><span><b>'+esc(i.quantity)+'</b> uds.</span></div>').join("")||'<div class="card muted">Inventario vacío.</div>')+'</div>'}
function showInventoryForm(){document.querySelector("#inventoryForm").innerHTML='<div class="card formcard"><h3>Nuevo artículo</h3><div class="formgrid"><input id="isk" placeholder="SKU"><input id="inm" placeholder="Nombre"><input id="iq" type="number" step="0.01" placeholder="Cantidad"><input id="irc" type="number" step="0.01" placeholder="Nivel reposición"><input id="ic" type="number" step="0.01" placeholder="Costo"><input id="ip" type="number" step="0.01" placeholder="Precio venta"><input id="il" placeholder="Ubicación"></div><button class="btn" onclick="saveInventory()">Guardar</button></div>'}
async function saveInventory(){const p={sku:document.querySelector("#isk").value.trim()||null,name:document.querySelector("#inm").value.trim(),quantity:+document.querySelector("#iq").value||0,reorder_level:+document.querySelector("#irc").value||0,unit_cost:+document.querySelector("#ic").value||0,sale_price:+document.querySelector("#ip").value||0,location:document.querySelector("#il").value.trim()};if(!p.name)return alert("Nombre requerido");const {error}=await supa.from("inventory_items").insert(p);if(error)return alert(error.message);inventory(document.querySelector("#content"))}
async function quotes(c){const [{data:list},{data:customers}]=await Promise.all([supa.from("quotes").select("*,customers(name),vehicles(year,make,model),quote_items(*)").order("created_at",{ascending:false}),supa.from("customers").select("id,name,vehicles(id,year,make,model)").order("name")]);window._financeCustomers=customers||[];c.innerHTML='<div class="sectionHead"><div><h1>Cotizaciones</h1><p class="muted">Crea estimados con partidas y conviértelos a factura.</p></div><button class="btn" onclick="showQuoteForm()">+ Cotización</button></div><div id="quoteForm"></div><div class="list">'+((list||[]).map(q=>'<div class="card"><div class="row"><span><b>COT-'+q.quote_number+'</b> · '+esc(q.customers?.name||"")+'<br><span class="muted">'+esc(q.vehicles?.year||"")+' '+esc(q.vehicles?.make||"")+' '+esc(q.vehicles?.model||"")+'</span></span><span>$'+Number(q.total||0).toFixed(2)+' · <span class="pill">'+esc(q.status)+'</span></span></div><div class="muted">'+(q.quote_items||[]).map(i=>esc(i.description)+' × '+esc(i.quantity)).join(" · ")+'</div>'+(q.status!=="converted"?'<button class="btn smallbtn" style="margin-top:10px" onclick="convertQuote(\''+q.id+'\')">Convertir a factura</button>':'')+'</div>').join("")||'<div class="card muted">No hay cotizaciones.</div>')+'</div>'}
function showQuoteForm(){const cs=window._financeCustomers||[];document.querySelector("#quoteForm").innerHTML='<div class="card formcard"><h3>Nueva cotización</h3><select id="qv"><option value="">Cliente / vehículo...</option>'+cs.flatMap(x=>(x.vehicles||[]).map(v=>'<option value="'+v.id+'" data-c="'+x.id+'">'+esc(x.name)+' · '+esc(v.year||"")+' '+esc(v.make||"")+' '+esc(v.model||"")+'</option>')).join("")+'</select><input id="qdesc" placeholder="Descripción de servicio o pieza"><input id="qqty" type="number" step="0.01" value="1"><input id="qprice" type="number" step="0.01" placeholder="Precio unitario"><input id="qtax" type="number" step="0.01" placeholder="Impuesto / IVU"><textarea id="qnotes" rows="3" placeholder="Notas"></textarea><button class="btn" onclick="saveQuote()">Guardar cotización</button></div>'}
async function saveQuote(){const s=document.querySelector("#qv"),vehicle_id=s.value,customer_id=s.selectedOptions[0]?.dataset.c,desc=document.querySelector("#qdesc").value.trim(),qty=+document.querySelector("#qqty").value||1,price=+document.querySelector("#qprice").value||0,tax=+document.querySelector("#qtax").value||0;if(!customer_id||!desc)return alert("Selecciona cliente y escribe la descripción.");const {data:q,error}=await supa.from("quotes").insert({customer_id,vehicle_id,status:"draft",tax,notes:document.querySelector("#qnotes").value.trim(),created_by:S.user.id}).select().single();if(error)return alert(error.message);const {error:itemErr}=await supa.from("quote_items").insert({quote_id:q.id,description:desc,quantity:qty,unit_price:price});if(itemErr)return alert(itemErr.message);await supa.rpc("recalculate_quote_totals",{p_quote:q.id});quotes(document.querySelector("#content"))}
async function convertQuote(id){const {data,error}=await supa.rpc("convert_quote_to_invoice",{p_quote:id});if(error)return alert(error.message);alert("Cotización convertida a factura.");S.current="Facturas";render()}

async function invoices(c){const [{data:list},{data:customers},{data:orders}]=await Promise.all([supa.from("invoices").select("*,customers(name),vehicles(year,make,model),invoice_items(*)").order("created_at",{ascending:false}),supa.from("customers").select("id,name,vehicles(id,year,make,model)").order("name"),supa.from("work_orders").select("id,order_number,title,customer_id,vehicle_id").order("created_at",{ascending:false})]);window._invoiceCustomers=customers||[];window._invoiceOrders=orders||[];c.innerHTML='<div class="sectionHead"><div><h1>Facturas</h1><p class="muted">Facturas, balances y pagos vinculados.</p></div><button class="btn" onclick="showInvoiceForm()">+ Factura</button></div><div id="invoiceForm"></div><div class="list">'+((list||[]).map(i=>'<div class="card"><div class="row"><span><b>FAC-'+i.invoice_number+'</b> · '+esc(i.customers?.name||"")+'<br><span class="muted">'+esc(i.vehicles?.year||"")+' '+esc(i.vehicles?.make||"")+' '+esc(i.vehicles?.model||"")+'</span></span><span>$'+Number(i.total||0).toFixed(2)+' · <span class="pill">'+esc(i.status)+'</span></span></div><div class="muted">Balance pendiente: $'+Number(i.balance_due||0).toFixed(2)+'</div><div class="muted">'+(i.invoice_items||[]).map(x=>esc(x.description)+' × '+esc(x.quantity)).join(" · ")+'</div></div>').join("")||'<div class="card muted">No hay facturas.</div>')+'</div>'}
function showInvoiceForm(){const cs=window._invoiceCustomers||[],os=window._invoiceOrders||[];document.querySelector("#invoiceForm").innerHTML='<div class="card formcard"><h3>Nueva factura</h3><select id="iv"><option value="">Cliente / vehículo...</option>'+cs.flatMap(x=>(x.vehicles||[]).map(v=>'<option value="'+v.id+'" data-c="'+x.id+'">'+esc(x.name)+' · '+esc(v.year||"")+' '+esc(v.make||"")+' '+esc(v.model||"")+'</option>')).join("")+'</select><select id="iwo"><option value="">Orden relacionada (opcional)</option>'+os.map(o=>'<option value="'+o.id+'">OT-'+o.order_number+' · '+esc(o.title)+'</option>').join("")+'</select><input id="idesc" placeholder="Descripción del trabajo o servicio"><input id="iqty" type="number" step="0.01" value="1"><input id="iprice" type="number" step="0.01" placeholder="Precio unitario"><input id="itax" type="number" step="0.01" placeholder="Impuesto / IVU"><button class="btn" onclick="saveInvoice()">Crear factura</button></div>'}
async function saveInvoice(){const s=document.querySelector("#iv"),vehicle_id=s.value,customer_id=s.selectedOptions[0]?.dataset.c,work_order_id=document.querySelector("#iwo").value||null,desc=document.querySelector("#idesc").value.trim(),qty=+document.querySelector("#iqty").value||1,price=+document.querySelector("#iprice").value||0,tax=+document.querySelector("#itax").value||0;if(!customer_id||!desc)return alert("Selecciona cliente y escribe la descripción.");const {data:inv,error}=await supa.from("invoices").insert({customer_id,vehicle_id,work_order_id,status:"draft",tax,created_by:S.user.id}).select().single();if(error)return alert(error.message);const {error:itemErr}=await supa.from("invoice_items").insert({invoice_id:inv.id,description:desc,quantity:qty,unit_price:price});if(itemErr)return alert(itemErr.message);await supa.rpc("recalculate_invoice_totals",{p_invoice:inv.id});invoices(document.querySelector("#content"))}

async function receipts(c){const [{data:list},{data:customers},{data:orders},{data:invoices}]=await Promise.all([supa.from("receipts").select("*,customers(name),work_orders(order_number),invoices(invoice_number)").order("created_at",{ascending:false}),supa.from("customers").select("id,name").order("name"),supa.from("work_orders").select("id,order_number,title,customer_id").order("created_at",{ascending:false}),supa.from("invoices").select("id,invoice_number,customer_id,total,balance_due,status").neq("status","void").order("created_at",{ascending:false})]);window._receiptCustomers=customers||[];window._receiptOrders=orders||[];window._receiptInvoices=invoices||[];c.innerHTML='<div class="sectionHead"><div><h1>Recibos</h1><p class="muted">Registra cobros y descuenta balances de factura.</p></div><button class="btn" onclick="showReceiptForm()">+ Recibo</button></div><div id="receiptForm"></div><div class="list">'+((list||[]).map(r=>'<div class="row"><span><b>REC-'+r.receipt_number+'</b> · '+esc(r.customers?.name||"")+'<br><span class="muted">'+(r.invoices?.invoice_number?'FAC-'+r.invoices.invoice_number+' · ':'')+(r.work_orders?.order_number?'OT-'+r.work_orders.order_number+' · ':'')+esc(r.payment_method||"")+'</span></span><span>$'+Number(r.amount||0).toFixed(2)+'</span></div>').join("")||'<div class="card muted">No hay recibos.</div>')+'</div>'}
function showReceiptForm(){const cs=window._receiptCustomers||[],os=window._receiptOrders||[],ins=window._receiptInvoices||[];document.querySelector("#receiptForm").innerHTML='<div class="card formcard"><h3>Nuevo recibo</h3><select id="rc"><option value="">Cliente...</option>'+cs.map(x=>'<option value="'+x.id+'">'+esc(x.name)+'</option>').join("")+'</select><select id="rinv"><option value="">Factura relacionada (opcional)</option>'+ins.map(i=>'<option value="'+i.id+'" data-c="'+i.customer_id+'">FAC-'+i.invoice_number+' · Balance $'+Number(i.balance_due||0).toFixed(2)+'</option>').join("")+'</select><select id="rwo"><option value="">Orden relacionada (opcional)</option>'+os.map(o=>'<option value="'+o.id+'" data-c="'+o.customer_id+'">OT-'+o.order_number+' · '+esc(o.title)+'</option>').join("")+'</select><input id="ramt" type="number" step="0.01" placeholder="Cantidad recibida"><select id="rpm"><option>Efectivo</option><option>ATH Móvil</option><option>Tarjeta</option><option>Cheque</option><option>Transferencia</option></select><input id="rref" placeholder="Referencia (opcional)"><textarea id="rnotes" rows="2" placeholder="Notas"></textarea><button class="btn" onclick="saveReceipt()">Guardar recibo</button></div>'}
async function saveReceipt(){const customer_id=document.querySelector("#rc").value,invoice_id=document.querySelector("#rinv").value||null,work_order_id=document.querySelector("#rwo").value||null,amount=+document.querySelector("#ramt").value||0;if(!customer_id||amount<=0)return alert("Selecciona cliente y cantidad válida.");const {error}=await supa.from("receipts").insert({customer_id,invoice_id,work_order_id,amount,payment_method:document.querySelector("#rpm").value,reference:document.querySelector("#rref").value.trim(),notes:document.querySelector("#rnotes").value.trim(),received_by:S.user.id});if(error)return alert(error.message);receipts(document.querySelector("#content"))}
async function pdfCenter(c){const [{data:qs},{data:ins},{data:rs}]=await Promise.all([supa.from("quotes").select("id,quote_number,total,status,customers(name)").order("created_at",{ascending:false}).limit(20),supa.from("invoices").select("id,invoice_number,total,balance_due,status,customers(name)").order("created_at",{ascending:false}).limit(20),supa.from("receipts").select("id,receipt_number,amount,payment_method,customers(name)").order("created_at",{ascending:false}).limit(20)]);c.innerHTML='<h1>PDF</h1><p class="muted">Exporta cotizaciones, facturas y recibos.</p><div class="dashboardActivity"><div class="card sectionCard"><h3>Cotizaciones</h3><div class="list">'+((qs||[]).map(q=>'<div class="row"><span>COT-'+q.quote_number+' · '+esc(q.customers?.name||"")+'</span><button class="btn smallbtn" onclick="exportQuotePdf(\''+q.id+'\')">PDF</button></div>').join("")||'<div class="muted">Sin cotizaciones.</div>')+'</div></div><div class="card sectionCard"><h3>Facturas</h3><div class="list">'+((ins||[]).map(i=>'<div class="row"><span>FAC-'+i.invoice_number+' · '+esc(i.customers?.name||"")+'</span><button class="btn smallbtn" onclick="exportInvoicePdf(\''+i.id+'\')">PDF</button></div>').join("")||'<div class="muted">Sin facturas.</div>')+'</div></div></div><div class="card sectionCard" style="margin-top:14px"><h3>Recibos</h3><div class="list">'+((rs||[]).map(r=>'<div class="row"><span>REC-'+r.receipt_number+' · '+esc(r.customers?.name||"")+'</span><button class="btn smallbtn" onclick="exportReceiptPdf(\''+r.id+'\')">PDF</button></div>').join("")||'<div class="muted">Sin recibos.</div>')+'</div></div>'}

async function urlToDataUrl(url){if(!url)return null;try{const r=await fetch(url,{cache:"no-store"});const b=await r.blob();return await new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(fr.result);fr.onerror=reject;fr.readAsDataURL(b)})}catch{return null}}
async function pdfHeader(doc,title,number,customer,vehicle,metaText=""){const orange=[244,122,31];doc.setFillColor(10,12,15);doc.rect(0,0,210,38,"F");doc.setFillColor(...orange);doc.rect(0,38,210,2.5,"F");let left=14;if(S.logoUrl){const data=await urlToDataUrl(S.logoUrl);if(data){try{const fmt=String(data).startsWith("data:image/jpeg")||String(data).startsWith("data:image/jpg")?"JPEG":String(data).startsWith("data:image/webp")?"WEBP":"PNG";doc.addImage(data,fmt,14,7,24,24);left=44}catch{}}}doc.setTextColor(255,255,255);doc.setFont("helvetica","bold");doc.setFontSize(18);doc.text(S.shop||"Mi Taller",left,14);doc.setFont("helvetica","normal");doc.setFontSize(8.8);const business=[S.businessPhone,S.businessEmail,S.businessAddress,S.businessWebsite].filter(Boolean).join("  ·  ");if(business)doc.text(business,left,21,{maxWidth:150});doc.setFont("helvetica","bold");doc.setFontSize(10);doc.text(title.toUpperCase()+"  "+number,left,31);doc.setTextColor(35,35,35);doc.setFont("helvetica","normal");doc.setFontSize(9.4);doc.text("Cliente",14,50);doc.setFont("helvetica","bold");doc.text(customer||"—",14,56);doc.setFont("helvetica","normal");if(vehicle){doc.text("Vehículo",110,50);doc.setFont("helvetica","bold");doc.text(vehicle,110,56,{maxWidth:86});doc.setFont("helvetica","normal")}if(metaText){doc.text(metaText,14,64,{maxWidth:182})}doc.setDrawColor(225,225,225);doc.line(14,69,196,69);return 78}
function pdfSectionTitle(doc,text,y){doc.setFillColor(245,246,248);doc.roundedRect(14,y-5,182,10,2,2,"F");doc.setTextColor(60,60,60);doc.setFont("helvetica","bold");doc.setFontSize(9.5);doc.text(text.toUpperCase(),18,y+1);doc.setFont("helvetica","normal");return y+12}
function pdfTotals(doc,subtotal,tax,total,balance,y){doc.setDrawColor(220,220,220);doc.line(120,y,196,y);y+=8;doc.setFontSize(10);doc.text("Subtotal",145,y,{align:"right"});doc.text("$"+Number(subtotal||0).toFixed(2),196,y,{align:"right"});y+=7;doc.text("IVU / Impuesto",145,y,{align:"right"});doc.text("$"+Number(tax||0).toFixed(2),196,y,{align:"right"});y+=9;doc.setFillColor(10,12,15);doc.roundedRect(118,y-6,78,12,2,2,"F");doc.setTextColor(255,255,255);doc.setFont("helvetica","bold");doc.setFontSize(12);doc.text("TOTAL",145,y+1,{align:"right"});doc.setTextColor(244,122,31);doc.text("$"+Number(total||0).toFixed(2),193,y+1,{align:"right"});doc.setTextColor(40,40,40);doc.setFont("helvetica","normal");if(balance!=null){y+=12;doc.setFontSize(10);doc.text("Balance pendiente: $"+Number(balance||0).toFixed(2),196,y,{align:"right"})}return y}
function pdfFooter(doc,label){const h=doc.internal.pageSize.getHeight();doc.setDrawColor(230,230,230);doc.line(14,h-18,196,h-18);doc.setFontSize(8);doc.setTextColor(120,120,120);doc.text((S.shop||"Mi Taller")+" · "+label,14,h-11);doc.text("Documento generado por el sistema administrativo del taller",196,h-11,{align:"right"})}
function savePdf(doc,name){doc.save(name+".pdf")}
async function exportQuotePdf(id){const {data:q,error}=await supa.from("quotes").select("*,customers(name,phone,email),vehicles(year,make,model,plate),quote_items(*)").eq("id",id).single();if(error||!q)return alert(error?.message||"No se pudo cargar.");const {jsPDF}=window.jspdf;const doc=new jsPDF();let y=await pdfHeader(doc,"Cotización de Servicio","COT-"+q.quote_number,q.customers?.name,[q.vehicles?.year,q.vehicles?.make,q.vehicles?.model,q.vehicles?.plate].filter(Boolean).join(" "),"Propuesta formal de trabajo y materiales para evaluación del cliente.");y=pdfSectionTitle(doc,"Detalle de servicios y materiales",y);doc.setFontSize(9);doc.setTextColor(80,80,80);doc.text("Descripción",14,y);doc.text("Cant.",138,y,{align:"right"});doc.text("Precio",165,y,{align:"right"});doc.text("Total",196,y,{align:"right"});y+=6;doc.setDrawColor(232,232,232);doc.line(14,y,196,y);y+=6;doc.setTextColor(35,35,35);for(const i of q.quote_items||[]){doc.text(i.description||"",14,y,{maxWidth:112});doc.text(String(i.quantity||1),138,y,{align:"right"});doc.text("$"+Number(i.unit_price||0).toFixed(2),165,y,{align:"right"});doc.text("$"+Number(i.line_total||0).toFixed(2),196,y,{align:"right"});y+=8}y=pdfTotals(doc,q.subtotal,q.tax,q.total,null,y+4);if(q.notes){y+=14;doc.setFont("helvetica","bold");doc.text("Notas",14,y);doc.setFont("helvetica","normal");y+=6;doc.text(q.notes,14,y,{maxWidth:182})}y+=18;doc.setDrawColor(160,160,160);doc.line(14,y,90,y);doc.line(112,y,196,y);doc.setFontSize(8);doc.setTextColor(110,110,110);doc.text("Firma del cliente",14,y+5);doc.text("Fecha de aprobación",112,y+5);pdfFooter(doc,"Cotización");savePdf(doc,"COT-"+q.quote_number)}
async function exportInvoicePdf(id){const {data:i,error}=await supa.from("invoices").select("*,customers(name,phone,email),vehicles(year,make,model,plate),work_orders(order_number),invoice_items(*)").eq("id",id).single();if(error||!i)return alert(error?.message||"No se pudo cargar.");const {jsPDF}=window.jspdf;const doc=new jsPDF();let y=await pdfHeader(doc,"Factura","FAC-"+i.invoice_number,i.customers?.name,[i.vehicles?.year,i.vehicles?.make,i.vehicles?.model,i.vehicles?.plate].filter(Boolean).join(" "),"Documento oficial de cobro por servicios y materiales suministrados"+(i.work_orders?.order_number?" · OT-"+i.work_orders.order_number:"")+".");y=pdfSectionTitle(doc,"Cargos facturados",y);doc.setFontSize(9);doc.setTextColor(80,80,80);doc.text("Descripción",14,y);doc.text("Cant.",138,y,{align:"right"});doc.text("Precio",165,y,{align:"right"});doc.text("Total",196,y,{align:"right"});y+=6;doc.setDrawColor(232,232,232);doc.line(14,y,196,y);y+=6;doc.setTextColor(35,35,35);for(const x of i.invoice_items||[]){doc.text(x.description||"",14,y,{maxWidth:112});doc.text(String(x.quantity||1),138,y,{align:"right"});doc.text("$"+Number(x.unit_price||0).toFixed(2),165,y,{align:"right"});doc.text("$"+Number(x.line_total||0).toFixed(2),196,y,{align:"right"});y+=8}y=pdfTotals(doc,i.subtotal,i.tax,i.total,i.balance_due,y+4);y+=14;doc.setFontSize(8.8);doc.setTextColor(90,90,90);doc.text("Estado: "+String(i.status||"").toUpperCase(),14,y);pdfFooter(doc,"Factura");savePdf(doc,"FAC-"+i.invoice_number)}
async function exportReceiptPdf(id){const {data:r,error}=await supa.from("receipts").select("*,customers(name,phone,email),work_orders(order_number),invoices(invoice_number,balance_due)").eq("id",id).single();if(error||!r)return alert(error?.message||"No se pudo cargar.");const {jsPDF}=window.jspdf;const doc=new jsPDF();let y=await pdfHeader(doc,"Recibo de Pago","REC-"+r.receipt_number,r.customers?.name,"","Confirmación de pago recibido por servicios, piezas o trabajos realizados.");y=pdfSectionTitle(doc,"Información del pago",y);doc.setFontSize(10);doc.setTextColor(50,50,50);doc.text("Cantidad recibida",14,y);doc.setFont("helvetica","bold");doc.setFontSize(18);doc.setTextColor(244,122,31);doc.text("$"+Number(r.amount||0).toFixed(2),196,y,{align:"right"});doc.setTextColor(50,50,50);doc.setFont("helvetica","normal");doc.setFontSize(10);y+=12;doc.text("Método de pago: "+(r.payment_method||"—"),14,y);y+=8;if(r.reference){doc.text("Referencia: "+r.reference,14,y);y+=8}if(r.invoices?.invoice_number){doc.text("Factura relacionada: FAC-"+r.invoices.invoice_number,14,y);y+=8}if(r.work_orders?.order_number){doc.text("Orden relacionada: OT-"+r.work_orders.order_number,14,y);y+=8}if(r.invoices?.balance_due!=null){doc.text("Balance restante de factura: $"+Number(r.invoices.balance_due||0).toFixed(2),14,y);y+=8}if(r.notes){y+=4;doc.setFont("helvetica","bold");doc.text("Notas",14,y);doc.setFont("helvetica","normal");y+=6;doc.text(r.notes,14,y,{maxWidth:182})}pdfFooter(doc,"Recibo de Pago");savePdf(doc,"REC-"+r.receipt_number)}

async function reports(c){const [{data:orders},{data:receipts},{data:inventory}]=await Promise.all([supa.from("work_orders").select("status"),supa.from("receipts").select("amount"),supa.from("inventory_items").select("quantity,reorder_level,unit_cost")]);const completed=(orders||[]).filter(o=>o.status==="closed").length,active=(orders||[]).filter(o=>!["closed","cancelled"].includes(o.status)).length,revenue=(receipts||[]).reduce((a,r)=>a+Number(r.amount||0),0),stock=(inventory||[]).reduce((a,i)=>a+Number(i.quantity||0)*Number(i.unit_cost||0),0);c.innerHTML='<h1>Reportes</h1><p class="muted">Indicadores operacionales.</p><div class="grid"><div class="metric">Activas<strong>'+active+'</strong></div><div class="metric">Cerradas<strong>'+completed+'</strong></div><div class="metric">Cobrado<strong>$'+revenue.toFixed(2)+'</strong></div><div class="metric">Valor inventario<strong>$'+stock.toFixed(2)+'</strong></div></div>'}
function settings(c){c.innerHTML='<h1>Ajustes</h1><p class="muted">Configura la identidad del taller y los datos que aparecerán en cotizaciones, facturas y recibos.</p><div class="card settings"><div class="logoBox">'+(S.logoUrl?'<img class="logoPreview" src="'+esc(S.logoUrl)+'" alt="Logo actual"><div class="muted small">Logo actual</div>':'<div class="logoPlaceholder">TA</div><div class="muted small">Aún no has subido un logo</div>')+'</div><label>Logo del taller</label><input id="logoFile" type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml"><div class="muted small">PNG, JPG, WEBP o SVG · máximo 5 MB</div><br><label>Nombre del negocio</label><input id="shop" value="'+esc(S.shop)+'"><label>Color principal</label><input id="color" type="color" value="'+S.brand+'"><div class="formgrid"><div><label>Teléfono</label><input id="businessPhone" value="'+esc(S.businessPhone)+'" placeholder="(787) 000-0000"></div><div><label>Email</label><input id="businessEmail" type="email" value="'+esc(S.businessEmail)+'" placeholder="info@taller.com"></div><div><label>Dirección</label><input id="businessAddress" value="'+esc(S.businessAddress)+'" placeholder="Dirección del taller"></div><div><label>Sitio web</label><input id="businessWebsite" value="'+esc(S.businessWebsite)+'" placeholder="www.taller.com"></div></div><button class="btn" onclick="saveSettings()">Guardar cambios</button></div>'}
async function saveSettings(){const btn=document.querySelector(".settings .btn");if(btn){btn.disabled=true;btn.textContent="Guardando..."}try{const shop=document.querySelector("#shop").value.trim()||"Mi Taller",brand=document.querySelector("#color").value,file=document.querySelector("#logoFile").files[0],businessPhone=document.querySelector("#businessPhone").value.trim(),businessEmail=document.querySelector("#businessEmail").value.trim(),businessAddress=document.querySelector("#businessAddress").value.trim(),businessWebsite=document.querySelector("#businessWebsite").value.trim();let logoPath=S.logoPath;if(file){if(file.size>5*1024*1024)throw new Error("El logo excede 5 MB.");const safe=file.name.replace(/[^a-zA-Z0-9._-]/g,"_");logoPath="logos/"+Date.now()+"-"+safe;const {error:upErr}=await supa.storage.from("branding").upload(logoPath,file,{cacheControl:"3600",upsert:false});if(upErr)throw upErr}const {error}=await supa.from("app_settings").update({shop_name:shop,brand_color:brand,logo_path:logoPath,business_phone:businessPhone,business_email:businessEmail,business_address:businessAddress,business_website:businessWebsite,updated_at:new Date().toISOString(),updated_by:S.user.id}).eq("id",1);if(error)throw error;S.shop=shop;S.brand=brand;S.logoPath=logoPath;S.businessPhone=businessPhone;S.businessEmail=businessEmail;S.businessAddress=businessAddress;S.businessWebsite=businessWebsite;S.logoUrl=null;if(logoPath){const {data:pub}=supa.storage.from("branding").getPublicUrl(logoPath);S.logoUrl=pub?.publicUrl||null}localStorage.shop=S.shop;localStorage.brand=S.brand;document.documentElement.style.setProperty("--brand",S.brand);alert("Ajustes guardados.");render()}catch(e){alert(e.message||"No se pudieron guardar los ajustes.")}finally{if(btn){btn.disabled=false;btn.textContent="Guardar cambios"}}}
init();if("serviceWorker" in navigator)navigator.serviceWorker.register("sw.js");